import sys

def factorial(n):
    if n <= 1:                 # base case
        return 1
    return n * factorial(n - 1)

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

print(factorial(10), gcd(1071, 462))

def forever(n):
    return forever(n + 1)      # no base case

