def fizzbuzz(n, rules=((3, "Fizz"), (5, "Buzz"))):
    result = []
    for i in range(1, n + 1):
        word = ""
        for divisor, text in rules:
            if i % divisor == 0:
                word += text
        result.append(word or str(i))
    return result

def primes_up_to(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
        p += 1
    return [i for i, flag in enumerate(is_prime) if flag]

def collatz_len(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

