#!/usr/bin/env python3
import sys

def expand_ports(spec):
    ports = set()
    for item in spec.split(","):
        item = item.strip()
        if not item:
            continue
        if "-" in item:
            low, high = item.split("-")
            ports.update(range(int(low), int(high) + 1))
        else:
            ports.add(int(item))
    return sorted(ports)

def main(argv):
    if len(argv) != 2:
        print("usage: portrange.py SPEC", file=sys.stderr)
        return 2
    for port in expand_ports(argv[1]):
        print(port)
    return 0

if __name__ == "__main__":
