    return True


def ip_to_int(ip):
    a, b, c, d = (int(p) for p in ip.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d


def int_to_ip(n):
    return ".".join(str((n >> shift) & 0xFF) for shift in (24, 16, 8, 0))


def prefix_to_mask(prefix):
    return (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF


def parse_cidr(text):
    ip, sep, bits = text.partition("/")
    if not sep or not valid_ipv4(ip) or not bits.isdigit() or int(bits) > 32:
        return None
    return ip, int(bits)


def describe(ip, prefix):
    mask = prefix_to_mask(prefix)
    network = ip_to_int(ip) & mask
    wildcard = ~mask & 0xFFFFFFFF
    broadcast = network | wildcard
    if prefix >= 31:                      # /31 and /32 have no network/broadcast pair
        first, last, hosts = network, broadcast, 2 ** (32 - prefix)
    else:
        first, last, hosts = network + 1, broadcast - 1, 2 ** (32 - prefix) - 2
    return {
        "network": int_to_ip(network),
        "mask": int_to_ip(mask),
        "wildcard": int_to_ip(wildcard),
        "broadcast": int_to_ip(broadcast),
        "first": int_to_ip(first),
        "last": int_to_ip(last),
        "hosts": hosts,
    }


def contains(cidr, ip):
    net_ip, prefix = cidr
    mask = prefix_to_mask(prefix)
    return ip_to_int(ip) & mask == ip_to_int(net_ip) & mask


