def ask(question):
    print(question)
    return input().strip()


def menu_loop():
    while True:
        print("1) describe a network  2) address in network?  3) binary  q) quit")
        choice = ask("choice?").lower()
        if choice == "q":
            print("bye")
            break
        if choice == "1":
            cidr = parse_cidr(ask("network (a.b.c.d/n)?"))
            if cidr is None:
                print("not a valid network")
                continue
            for key, value in describe(*cidr).items():
                print(f"  {key:<10}{value}")
        elif choice == "2":
            cidr = parse_cidr(ask("network (a.b.c.d/n)?"))
            ip = ask("address?")
            if cidr is None or not valid_ipv4(ip):
                print("not a valid network or address")
                continue
            print("  inside" if contains(cidr, ip) else "  outside")
        elif choice == "3":
            ip = ask("address?")
            if not valid_ipv4(ip):
                print("not a valid address")
                continue
            print("  " + ".".join(f"{int(o):08b}" for o in ip.split(".")))
        else:
            print("unknown choice", repr(choice))


menu_loop()
